// [SALA] Vigía del silencio · el que DECIDE · E59 · CC#1 · 2026-09-16
//
// 🔴 POR QUÉ EXISTE: la regla 4 del manual del 30-may decía «siete días sin
// novedad → archivar y avisar a un humano». Se perdió entre un documento y el
// siguiente y NUNCA se construyó. Costo: ~26.700 vueltas de reloj en verde con
// CERO despachos, tres meses, y nadie se enteró.
//
// 🔴 LO QUE MIRA: lo que NO pasó. Los otros 48 avisos de la casa miran lo que sí
// ocurrió; el único que mira silencio mira el equivocado (procesos colgados EN
// corrida), no una corrida que terminó bien y cuyo despacho siguiente nunca fue.
//
// 🔴 LO QUE NO TIENE, A PROPÓSITO: interruptor de silencio. No hay «apagar
// alarma», no hay «no molestar», y un umbral ilegible NO la apaga: usa el de
// fábrica y lo DICE. Canon: «un freno que no frena es peor que ninguno».
// E62 · CC#1 · 2026-09-16 · post certificación E60 (CC#3 ×2): forzar_aviso se lee
// de la PUERTA (no de $input) · un libro ilegible es NO_SE_PUDO_SABER, nunca un hecho ·
// el lunes grita en UNA vuelta · la causa del aviso es la MEDIDA en esta corrida.
const HORAS_POR_DEFECTO = 48;

const ahora = new Date();
// ── ⓪ ¿me pidieron gritar? · SOLO existe cuando entra por la puerta · en la vuelta del
// reloj ese nodo no corrió y $('Puerta…') lanza ⇒ try/catch obligatorio.
let entrada = {};
try { const p = $('Puerta · preguntar a pedido').first().json; entrada = (p && p.body) || {}; } catch (e) { entrada = {}; }
const forzado = String(entrada.forzar_aviso) === 'true';
// la vuelta diaria del reloj · cron 0 */6 en la zona del motor (America/New_York) ⇒
// 04/10/16/22 UTC · la de las 04 UTC (00 NY) es la única que grita en los estados con freno.
const vueltaDiaria = ahora.getUTCHours() < 6;

// ── ① el umbral · vive en UNA fila de `settings`, cambiable sin desplegar ──
let horas = HORAS_POR_DEFECTO;
let umbralDeDonde = 'el de fábrica · NO se pudo leer la fila `sala.silencio_max_horas`';
try {
  const fila = $('El umbral del silencio').first().json;
  const f = Array.isArray(fila) ? (fila[0] || {}) : (fila || {});
  const crudo = f.value;
  // regla estricta y declarada · no se adivina el formato (lección del % de la casa)
  if (crudo !== undefined && crudo !== null && /^[0-9]+(\.[0-9]+)?$/.test(String(crudo))) {
    const n = Number(crudo);
    // 🔴 un umbral de cero o gigante NO apaga la alarma: se ignora y se declara.
    if (n > 0 && n <= 720) {
      horas = n;
      umbralDeDonde = 'settings · sala.silencio_max_horas = ' + crudo;
    } else {
      umbralDeDonde = 'la fila decia ' + JSON.stringify(crudo) + ' · fuera de rango (0 < h <= 720) · uso el de fabrica';
    }
  } else if (crudo !== undefined) {
    umbralDeDonde = 'la fila decia ' + JSON.stringify(crudo) + ' · no es un numero · uso el de fabrica';
  }
} catch (e) {
  umbralDeDonde = 'no se pudo leer el nodo del umbral · ' + e.message + ' · uso el de fabrica';
}

// ── ② ¿la sala está ENCENDIDA o APAGADA? · hueco ③ de E54 ──
// Lo que hace latir a la sala es el reloj del repartidor. Si ese flujo está
// apagado, la sala está muda A PROPÓSITO y esta alarma NO grita.
let relojEncendido = null;
let relojDetalle = 'no se pudo leer el estado del reloj del repartidor';
try {
  const r = $('El reloj de la sala').first().json;
  const w = Array.isArray(r) ? (r[0] || {}) : (r || {});
  if (typeof w.active === 'boolean') {
    relojEncendido = w.active;
    relojDetalle = 'flujo ' + (w.id || 'z2nS8Up115EA9TKz') + ' · activo=' + w.active;
  } else {
    // la causa MEDIDA en esta corrida, no una fija
    relojDetalle = 'no se pudo leer el estado del reloj del repartidor · el motor respondio: ' + JSON.stringify(w).slice(0, 160);
  }
} catch (e) {
  relojDetalle = 'no se pudo leer el estado del reloj · ' + e.message;
}

// ── ③ el latido POR RECORRIDO · cuándo se movió por última vez cada uno ──
// 🔴 el nodo del libro devuelve la respuesta ENTERA ({statusCode, body}) · un error de la
// base NO es un asiento y una tabla vacia NO es un error: se distinguen aca, con nombre.
let eventos = [];
let libroLegible = false;
let libroDetalle = 'no se pudo leer el nodo del libro';
try {
  const r = $('El libro de la sala').first().json || {};
  const sc = Number(r.statusCode);
  const body = r.body;
  const esAsiento = function (e) { return e && typeof e === 'object' && Object.prototype.hasOwnProperty.call(e, 'occurred_at'); };
  if (sc >= 200 && sc < 300 && Array.isArray(body) && body.every(esAsiento)) {
    eventos = body;
    libroLegible = true;
    libroDetalle = 'HTTP ' + sc + ' · ' + body.length + ' asientos';
  } else {
    libroDetalle = 'HTTP ' + (isNaN(sc) ? '?' : sc) + ' · la respuesta NO es un libro · ' + JSON.stringify(body === undefined ? r : body).slice(0, 160);
  }
} catch (e) {
  libroDetalle = 'no se pudo leer el nodo del libro · ' + e.message;
}
const latido = {};
for (const e of eventos) {
  const j = e.journey_type || 'SIN_RECORRIDO';
  const t = e.occurred_at || e.created_at;
  if (!t) continue;
  if (!latido[j] || new Date(t) > new Date(latido[j])) latido[j] = t;
}
const horasDesde = function (t) { return t ? (ahora - new Date(t)) / 36e5 : null; };

// ── ④ lo que NO pasó ──
const esIntake = function (e) { return typeof e.step_id === 'string' && e.step_id.indexOf('intake.') === 0; };
const esDespacho = function (e) { return typeof e.step_id === 'string' && e.step_id.indexOf('router.dispatch.') === 0; };
const esRendicion = function (e) { return typeof e.step_id === 'string' && e.step_id.indexOf('router.giveup.') === 0; };

const cerrados = {};
for (const e of eventos) { if (esDespacho(e) || esRendicion(e)) cerrados[e.stream_id] = true; }
const sobresSinDespachar = eventos
  .filter(esIntake)
  .filter(function (e) { return !cerrados[e.stream_id]; })
  .filter(function (e) { return horasDesde(e.occurred_at) > horas; });

const despachos = eventos.filter(esDespacho).map(function (e) { return e.occurred_at; }).sort();
const ultimoDespacho = despachos.length ? despachos[despachos.length - 1] : null;
const horasSinDespachar = ultimoDespacho ? horasDesde(ultimoDespacho) : null;

// ── ⑤ el veredicto ──
// 🔴 La regla que da sentido a todo esto: un verde que no distingue «no habia
// nada que hacer» de «no despache nada» NO es un verde.
let estado, grita = false, titulo = '', detalle = '', queHacer = '';

if (!libroLegible) {
  // 🔴 la enfermedad de la casa: una consulta que falla y se lee como tranquilidad.
  // Un libro que no se pudo leer NO es un libro con un asiento ni un libro vacio: es NO SE.
  estado = 'NO_SE_PUDO_SABER';
  grita = vueltaDiaria || forzado;
  titulo = 'NO SE PUDO LEER EL LIBRO DE LA SALA';
  detalle = 'libro: ' + libroDetalle + ' · reloj: ' + relojDetalle;
  queHacer = 'esta alarma no puede afirmar nada sobre la sala sin el libro · mira la respuesta de la base (permisos, tabla, timeout) antes de confiar en cualquier verde.';
} else if (relojEncendido === false) {
  estado = 'APAGADA_A_PROPOSITO';
  titulo = 'la sala esta apagada · no grito';
  detalle = relojDetalle;
  queHacer = 'nada · si tenia que estar encendida, encende el reloj del repartidor';
} else if (sobresSinDespachar.length > 0) {
  estado = 'TRABAJO_SIN_DESPACHAR';
  grita = true;
  titulo = 'HAY TRABAJO SIN DESPACHAR · ' + sobresSinDespachar.length + ' sobre(s) esperando hace mas de ' + horas + ' h';
  detalle = sobresSinDespachar.slice(0, 5).map(function (e) {
    return '· ' + e.step_id + ' · cliente ' + String(e.client_id).slice(0, 8) + ' · hace ' + Math.round(horasDesde(e.occurred_at)) + ' h';
  }).join('\n');
  queHacer = 'mira el registro del repartidor: o el destino no esta en el mapa, o el despacho falla. Si hay marcas `router.giveup.*`, el motivo esta escrito ahi.';
} else if (relojEncendido === true && ultimoDespacho === null) {
  // el caso EXACTO que nos paso: reloj girando, cero despachos, todo verde
  const fechas = eventos.map(function (e) { return e.occurred_at; }).filter(Boolean).sort();
  const dias = fechas.length ? Math.round(horasDesde(fechas[0]) / 24) : 0;
  estado = 'ENCENDIDA_Y_MUDA';
  // 🔴 grita UNA VEZ POR SEMANA, no todos los dias: una alarma de silencio
  // ruidosa se silencia, y el dia que grite de verdad nadie la mira.
  grita = (ahora.getUTCDay() === 1 && vueltaDiaria) || forzado;  // UNA vuelta: lunes 04 UTC (00 NY)
  titulo = 'LA SALA ESTA ENCENDIDA Y NUNCA DESPACHO NADA';
  detalle = 'el reloj late cada 3 minutos · el libro tiene ' + eventos.length + ' asientos y CERO despachos'
    + (dias ? ' · el asiento mas viejo es de hace ' + dias + ' dias' : '');
  queHacer = 'esto NO es «no habia nada que hacer»: es que nadie dejo un sobre. Comproba que el que deberia dejarlo (el alta al terminar) lo este dejando.';
} else if (relojEncendido === true && horasSinDespachar !== null && horasSinDespachar > horas) {
  estado = 'SIN_DESPACHAR_HACE_RATO';
  grita = true;
  titulo = 'la sala no despacha hace ' + Math.round(horasSinDespachar) + ' h (umbral ' + horas + ' h)';
  detalle = 'ultimo despacho: ' + ultimoDespacho;
  queHacer = 'si se esperaban sobres en este tiempo, algo dejo de dejarlos. Si no se esperaban, baja el umbral o deja constancia.';
} else if (relojEncendido === null) {
  estado = 'NO_SE_PUDO_SABER';
  // 🔴 no saber NO es estar bien: grita. Pero UNA VEZ POR DIA (la vuelta de las
  // 00 UTC), no en las cuatro vueltas: una alarma repetida se silencia, y el dia
  // que grite de verdad nadie la mira. Sigue sin haber forma de apagarla.
  grita = vueltaDiaria || forzado;
  titulo = 'NO SE PUDO SABER SI LA SALA ESTA VIVA';
  detalle = relojDetalle;
  queHacer = 'la lectura del reloj del repartidor fallo · si el motor respondio «X-N8N-API-KEY header required», '
    + 'falta la credencial del motor en su propio entorno · hasta que se lea, esta alarma NO puede '
    + 'distinguir «apagada a proposito» de «rota», y lo dice en vez de suponer.';
} else {
  estado = 'AL_DIA';
  titulo = 'la sala despacho hace ' + Math.round(horasSinDespachar) + ' h · dentro del umbral';
  detalle = 'ultimo despacho: ' + ultimoDespacho;
  queHacer = '';
}

return [{ json: {
  estado: estado, grita: grita, titulo: titulo, detalle: detalle, que_hacer: queHacer,
  umbral_horas: horas, umbral_de_donde: umbralDeDonde,
  reloj: relojDetalle,
  libro: libroDetalle,
  pedido_forzado: forzado,
  latido_por_recorrido: Object.keys(latido).map(function (j) {
    return { recorrido: j, ultimo_movimiento: latido[j], hace_horas: Math.round(horasDesde(latido[j])) };
  }),
  sobres_sin_despachar: sobresSinDespachar.length,
  ultimo_despacho: ultimoDespacho,
  asientos_leidos: eventos.length,
  medido_en: ahora.toISOString(),
} }];

// 🔴 el silencio legítimo TAMBIÉN deja rastro · si nadie ve esto, nadie puede
// afirmar que la alarma corrió. No manda aviso: sólo queda en el registro.
const v = $input.first().json;
console.log('[vigia-silencio] ' + v.estado + ' · ' + v.titulo + ' · umbral ' + v.umbral_horas + ' h · ' + v.umbral_de_donde);
return [{ json: v }];
